#[derive(Debug, thiserror::Error)]
pub enum ClientError {
    #[error("st client API error {0:?}: {1}")]
    Api(ErrorCode, String, Box<ErrorEnvelope>),
    #[error("st client transport error: {0}")]
    Transport(String),
    #[error(transparent)]
    Unreachable(DaemonUnreachable),
    #[error("st client protocol error: {0}")]
    Protocol(String),
}

impl ClientError {
    /// What went wrong in words a person reads: no codes and no Rust names. st's own message
    /// follows where it says something the sentence does not.
    pub fn plain(&self) -> String {
        match self {
            ClientError::Api(code, message, _) => plain_message(Some(code), message),
            ClientError::Transport(message) if message.contains("deadline") => {
                "st took too long to answer; it may or may not have done it".into()
            }
            ClientError::Transport(message) => format!("the connection to st broke ({message})"),
            ClientError::Unreachable(unreachable) => {
                format!(
                    "st is not answering at {} (restarting?)",
                    unreachable.endpoint
                )
            }
            ClientError::Protocol(message) => {
                format!("st sent something this client cannot read ({message})")
            }
        }
    }

    /// Whether the same request may succeed if tried again after a short wait: it raced a busy
    /// store, st was restarting or slow, or another host was briefly out of reach. A refusal
    /// about the thing itself (gone, not allowed, invalid) is not.
    pub fn is_transient(&self) -> bool {
        match self {
            ClientError::Api(code, _, envelope) => {
                envelope.retryable
                    || matches!(
                        code,
                        ErrorCode::StaleFence
                            | ErrorCode::PageCursorExpired
                            | ErrorCode::CursorGap
                            | ErrorCode::RemoteUnavailable
                            | ErrorCode::RateLimited
                            | ErrorCode::RuntimeAuthorityIndeterminate
                            | ErrorCode::TerminalUnavailable
                            | ErrorCode::Internal
                    )
            }
            ClientError::Transport(_) | ClientError::Unreachable(_) => true,
            ClientError::Protocol(_) => false,
        }
    }
}

/// An error st sent (a code, when it gave one, and its message) as a person reads it.
pub fn plain_message(code: Option<&ErrorCode>, message: &str) -> String {
    let Some(code) = code else {
        return message.to_owned();
    };
    let host = message
        .split_whitespace()
        .find_map(|word| word.strip_prefix("host/"))
        .map(|host| host.trim_end_matches(|c: char| !c.is_alphanumeric()));
    match code {
        ErrorCode::StaleFence => {
            "st changed while this was on its way, so it was not applied".into()
        }
        ErrorCode::PageCursorExpired | ErrorCode::CursorGap => {
            "the list changed while it was being read".into()
        }
        ErrorCode::RemoteUnavailable => match host {
            Some(host) => format!("{host} cannot be reached right now"),
            None => "the host this lives on cannot be reached right now".into(),
        },
        ErrorCode::RateLimited => "st asked to slow down for a moment".into(),
        ErrorCode::RuntimeAuthorityIndeterminate => {
            "st cannot tell yet which host runs this".into()
        }
        ErrorCode::IdempotencyConflict => {
            "this was already sent once in another form, so it was not sent again".into()
        }
        ErrorCode::UnsupportedCapability => {
            format!("this st does not do that yet ({message})")
        }
        ErrorCode::NotFound => format!("it is gone: {message}"),
        ErrorCode::Forbidden => format!("not allowed: {message}"),
        ErrorCode::Internal => format!("st hit a problem: {message}"),
        ErrorCode::TimelineHistoryIncomplete => message.to_owned(),
        ErrorCode::TerminalEnded => "the terminal ended: its process exited".into(),
        ErrorCode::TerminalUnavailable => "the terminal cannot be reached right now".into(),
        ErrorCode::BlobTooLarge => "the image is too large; the limit is 10 MiB".into(),
        ErrorCode::UnsupportedMediaType => {
            "only PNG, JPEG, GIF and WebP images can be attached".into()
        }
        ErrorCode::BlobContentMismatch => "the file is not the kind of image it says it is".into(),
        ErrorCode::BlobQuotaExceeded => {
            "too many images were uploaded recently; try again later".into()
        }
        ErrorCode::BlobNotFound => "this image is not stored on this machine".into(),
        ErrorCode::BlobExpired => {
            "this image was removed after its retention window; the message text remains".into()
        }
        ErrorCode::ValidationFailed
        | ErrorCode::AttentionMigrated
        | ErrorCode::RuntimeNotLocal
        | ErrorCode::Unknown => message.to_owned(),
    }
}

/// Run `attempt` until it succeeds, its error is not transient, or `tries` run out, waiting a
/// little longer each time (50 ms doubling, up to 2 s). Each try builds its request afresh, so a
/// fence read inside it is current; an action that may have been applied (a transport error
/// after sending) must reuse its idempotency key, which the caller keeps outside the closure.
pub async fn retry_transient<T, F, Fut>(tries: u32, mut attempt: F) -> Result<T, ClientError>
where
    F: FnMut(u32) -> Fut,
    Fut: std::future::Future<Output = Result<T, ClientError>>,
{
    let mut wait = Duration::from_millis(50);
    let mut try_number = 0;
    loop {
        match attempt(try_number).await {
            Ok(value) => return Ok(value),
            Err(error) if error.is_transient() && try_number + 1 < tries => {
                tokio::time::sleep(wait).await;
                wait = (wait * 2).min(Duration::from_secs(2));
                try_number += 1;
            }
            Err(error) => return Err(error),
        }
    }
}

/// The st daemon accepted no connection, typically because it is restarting. Nothing was sent,
/// so the request is always safe to repeat.
