    async fn terminal_screen_at(
        &self,
        terminal_id: &str,
        after: Option<(&str, u64)>,
        facts: bool,
    ) -> Result<Envelope<TerminalScreen>, ClientError> {
        let mut query = Vec::new();
        if let Some((after_revision, wait_ms)) = after {
            query.push(format!("after={}", percent_encode(after_revision)));
            query.push(format!("wait_ms={wait_ms}"));
        }
        if facts {
            query.push("facts=true".to_owned());
        }
        let query = if query.is_empty() {
            String::new()
        } else {
            format!("?{}", query.join("&"))
        };
        self.get(&format!(
            "/v1/client/terminals/{}/screen{query}",
            percent_encode_segment(terminal_id.trim_start_matches("terminal/"))
        ))
        .await
    }

    /// Acquire a fresh, single-use capability for a fenced raw PTY connection.
    /// Reconnecting consumers must call this again rather than replaying a capability.
    pub async fn raw_terminal_attachment(
        &self,
        terminal_id: &str,
        runtime_incarnation: &str,
        mode: RawTerminalMode,
    ) -> Result<RawTerminalAttachment, ClientError> {
        self.post::<Envelope<RawTerminalAttachment>>(
            &format!(
                "/v1/client/terminals/{}/raw-attachments",
                percent_encode_segment(terminal_id.trim_start_matches("terminal/"))
            ),
            &RawTerminalAttachmentRequest {
                runtime_incarnation: runtime_incarnation.to_owned(),
                mode,
            },
        )
        .await
        .map(|response| response.value)
    }

    /// Consume a capability and return a PTY-compatible Unix connector.
    ///
    /// The caller writes its own ATTACH or PEEK frame. This transport neither parses nor
    /// synthesizes PTY protocol frames. Dropping the returned stream cancels the bounded
    /// bridge, including while either direction is backpressured.
    pub async fn raw_terminal_stream(
        &self,
        attachment: &RawTerminalAttachment,
    ) -> Result<tokio::net::UnixStream, ClientError> {
        let path = format!(
            "/v1/client/terminals/{}/raw-stream?incarnation={}&mode={}",
            percent_encode_segment(attachment.terminal_id.trim_start_matches("terminal/")),
            percent_encode(&attachment.runtime_incarnation),
            attachment.mode.as_str(),
        );
        let request_for = |base: &str| -> Result<Request<()>, ClientError> {
            let mut request = websocket_request(
                &format!("{base}{path}"),
                self.credential.as_deref(),
                self.local_person.as_deref(),
                None,
            )?;
            request.headers_mut().insert(
                hyper::header::SEC_WEBSOCKET_PROTOCOL,
                hyper::header::HeaderValue::from_str(&format!(
                    "{RAW_TERMINAL_SUBPROTOCOL}, st3.cap.{}",
                    attachment.stream_capability
                ))
                .map_err(|error| ClientError::Protocol(error.to_string()))?,
            );
            Ok(request)
        };
        let config = WebSocketConfig::default()
            .max_message_size(Some(HARD_MAX_RESPONSE_BYTES))
            .max_frame_size(Some(HARD_MAX_RESPONSE_BYTES));
        match &self.endpoint {
            Endpoint::Unix(socket) => {
                let stream = tokio::time::timeout(
                    STREAM_HANDSHAKE_DEADLINE,
                    tokio::net::UnixStream::connect(socket),
                )
                .await
                .map_err(|_| {
                    ClientError::Transport("raw terminal connect deadline exceeded".into())
                })?
                .map_err(|error| unreachable_error(&socket.display().to_string(), &error))?;
                let (websocket, response) = tokio::time::timeout(
                    STREAM_HANDSHAKE_DEADLINE,
                    tokio_tungstenite::client_async_with_config(
                        request_for("ws://localhost")?,
                        stream,
                        Some(config),
                    ),
                )
                .await
                .map_err(|_| {
                    ClientError::Transport("raw terminal handshake deadline exceeded".into())
                })?
                .map_err(|error| ClientError::Transport(error.to_string()))?;
                validate_raw_terminal_subprotocol(&response)?;
                raw_terminal_connector(websocket)
            }
            Endpoint::FabricLoopback(base) => {
                let websocket_base = if let Some(base) = base.strip_prefix("https://") {
                    format!("wss://{base}")
                } else if let Some(base) = base.strip_prefix("http://") {
                    format!("ws://{base}")
                } else {
                    return Err(ClientError::Protocol(
                        "gateway endpoint must use http or https".into(),
                    ));
                };
                let (websocket, response) = tokio::time::timeout(
                    STREAM_HANDSHAKE_DEADLINE,
                    tokio_tungstenite::connect_async_with_config(
                        request_for(&websocket_base)?,
                        Some(config),
                        false,
                    ),
                )
                .await
                .map_err(|_| {
                    ClientError::Transport("raw terminal handshake deadline exceeded".into())
                })?
                .map_err(|error| ClientError::Transport(error.to_string()))?;
                validate_raw_terminal_subprotocol(&response)?;
                raw_terminal_connector(websocket)
            }
        }
    }

    /// Open the terminal stream that one `terminal.attach` capability allows.
    pub async fn terminal_stream(
        &self,
        terminal_id: &str,
        incarnation: Option<&str>,
        stream_capability: &str,
    ) -> Result<TerminalStream, ClientError> {
        let suffix = incarnation
            .map(|incarnation| format!("?incarnation={}", percent_encode(incarnation)))
            .unwrap_or_default();
        let path = format!(
            "/v1/client/terminals/{}/stream{suffix}",
            percent_encode_segment(terminal_id.trim_start_matches("terminal/"))
        );
        let socket = match &self.endpoint {
            Endpoint::Unix(socket) => {
                let stream = tokio::time::timeout(
                    STREAM_HANDSHAKE_DEADLINE,
                    tokio::net::UnixStream::connect(socket),
                )
                .await
                .map_err(|_| {
                    ClientError::Transport("terminal stream connect deadline exceeded".into())
                })?
                .map_err(|error| unreachable_error(&socket.display().to_string(), &error))?;
                let request = websocket_request(
                    &format!("ws://localhost{path}"),
                    self.credential.as_deref(),
                    self.local_person.as_deref(),
                    Some(stream_capability),
                )?;
                let (websocket, response) = tokio::time::timeout(
                    STREAM_HANDSHAKE_DEADLINE,
                    tokio_tungstenite::client_async(request, stream),
                )
                .await
                .map_err(|_| {
                    ClientError::Transport("terminal WebSocket handshake deadline exceeded".into())
                })?
                .map_err(|error| ClientError::Transport(error.to_string()))?;
                validate_terminal_subprotocol(&response)?;
                TerminalSocket::Unix(websocket)
            }
            Endpoint::FabricLoopback(base) => {
                let websocket_base = if let Some(base) = base.strip_prefix("https://") {
                    format!("wss://{base}")
                } else if let Some(base) = base.strip_prefix("http://") {
                    format!("ws://{base}")
                } else {
                    return Err(ClientError::Protocol(
                        "Fabric loopback endpoint must use http or https".into(),
                    ));
                };
                let request = websocket_request(
                    &format!("{websocket_base}{path}"),
                    self.credential.as_deref(),
                    None,
                    Some(stream_capability),
                )?;
                let (websocket, response) =
                    tokio::time::timeout(STREAM_HANDSHAKE_DEADLINE, connect_async(request))
                        .await
                        .map_err(|_| {
                            ClientError::Transport(
                                "terminal WebSocket handshake deadline exceeded".into(),
                            )
                        })?
                        .map_err(|error| ClientError::Transport(error.to_string()))?;
                validate_terminal_subprotocol(&response)?;
                TerminalSocket::Remote(websocket)
            }
        };
        Ok(TerminalStream {
            socket,
            limit: self.response_limit(),
        })
    }

